CREATE TYPE public.app_role AS ENUM ('aie','centro','familia');
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(uid uuid, wanted public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=uid AND role=wanted) $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', zone text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', avatar_path text, cv_path text, available boolean NOT NULL DEFAULT true, skills text[] NOT NULL DEFAULT '{}', verified boolean NOT NULL DEFAULT false, public_profile boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.profiles TO anon,authenticated; GRANT UPDATE(name,zone,bio,avatar_path,cv_path,available,skills) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY visible_profiles ON public.profiles FOR SELECT TO anon,authenticated USING(public_profile OR id=auth.uid());
CREATE POLICY update_own_profile ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.family_needs (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, needs text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,UPDATE ON public.family_needs TO authenticated; GRANT ALL ON public.family_needs TO service_role;
ALTER TABLE public.family_needs ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_family ON public.family_needs FOR ALL TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'familia')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'familia'));
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE selected public.app_role; BEGIN selected := CASE WHEN NEW.raw_user_meta_data->>'role'='centro' THEN 'centro'::public.app_role WHEN NEW.raw_user_meta_data->>'role'='familia' THEN 'familia'::public.app_role ELSE 'aie'::public.app_role END; INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,selected); INSERT INTO public.profiles(id,name,public_profile) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name',NEW.raw_user_meta_data->>'full_name',''),selected<>'familia'); IF selected='familia' THEN INSERT INTO public.family_needs(user_id) VALUES(NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER on_acompaname_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, organization text NOT NULL, title text NOT NULL, zone text NOT NULL, schedule text NOT NULL, skills text[] NOT NULL DEFAULT '{}', description text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.jobs TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.jobs TO authenticated; GRANT ALL ON public.jobs TO service_role;
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_jobs ON public.jobs FOR SELECT TO anon,authenticated USING(active OR owner_id=auth.uid());
CREATE POLICY manage_jobs ON public.jobs FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid() AND (public.has_role(auth.uid(),'centro') OR public.has_role(auth.uid(),'familia')));
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(job_id,user_id));
GRANT SELECT,INSERT ON public.applications TO authenticated; GRANT ALL ON public.applications TO service_role;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_applications ON public.applications FOR SELECT TO authenticated USING(user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.owner_id=auth.uid()));
CREATE POLICY apply_as_aie ON public.applications FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'aie') AND EXISTS(SELECT 1 FROM public.jobs j WHERE j.id=job_id AND j.active));
CREATE TABLE public.posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, author_name text NOT NULL, content text NOT NULL, kind text NOT NULL DEFAULT 'logro', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.posts TO anon; GRANT SELECT,INSERT,DELETE ON public.posts TO authenticated; GRANT ALL ON public.posts TO service_role;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_posts ON public.posts FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY create_posts ON public.posts FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid());
CREATE POLICY delete_own_posts ON public.posts FOR DELETE TO authenticated USING(author_id=auth.uid());
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(sender_id<>recipient_id));
GRANT SELECT,INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_messages ON public.messages FOR SELECT TO authenticated USING(sender_id=auth.uid() OR recipient_id=auth.uid());
CREATE POLICY send_messages ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND sender_id<>recipient_id);
CREATE INDEX message_participants ON public.messages(sender_id,recipient_id,created_at);
CREATE INDEX jobs_created ON public.jobs(created_at DESC);
CREATE INDEX posts_created ON public.posts(created_at DESC);